"use client";

import Link from "next/link";
import { useEffect, useMemo, useState } from "react";
import AppShell from "@/components/Navbar";
import { api } from "@/lib/api";
import type { UserRole } from "@/config/navigation/types";

type Role = "Admin" | "Instructor" | "Student";

interface Department {
  id: number;
  name: string;
  code: string;
}

interface UserProfile {
  id: number;
  employee_id: string | null;
  student_id: string | null;
  email: string;
  first_name: string;
  last_name: string;
  dept_id: number;
  department?: Department;
  role: Role;
  is_irregular: boolean;
  is_active: boolean;
  created_at: string;
}

interface ApiEnvelope<T> {
  success: boolean;
  message: string;
  data: T;
  errors?: Record<string, string[]>;
}

function getInitials(first: string, last: string) {
  return `${first.charAt(0)}${last.charAt(0)}`.toUpperCase();
}

function formatDate(iso: string) {
  return new Date(iso).toLocaleDateString("en-PH", { year: "numeric", month: "long", day: "numeric" });
}

export default function ProfilePage() {
  const initialRole = useMemo<UserRole>(() => {
    if (typeof document === "undefined") return "student";
    const roleCookie = document.cookie
      .split("; ")
      .find((c) => c.startsWith("role="))
      ?.split("=")[1];
    const decoded = roleCookie ? decodeURIComponent(roleCookie) : "";
    if (decoded === "Admin") return "admin";
    if (decoded === "Instructor") return "instructor";
    return "student";
  }, []);
  const [user, setUser] = useState<UserProfile | null>(null);
  const [firstName, setFirstName] = useState("");
  const [lastName, setLastName] = useState("");
  const [email, setEmail] = useState("");
  const [loading, setLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [saveStatus, setSaveStatus] = useState<"idle" | "success" | "error">("idle");
  const [errorMsg, setErrorMsg] = useState("");

  useEffect(() => {
    let active = true;
    async function loadProfile() {
      setLoading(true);
      setErrorMsg("");
      try {
        const res = await api.get<ApiEnvelope<UserProfile>>("/profile");
        if (!active) return;
        setUser(res.data);
        setFirstName(res.data.first_name);
        setLastName(res.data.last_name);
        setEmail(res.data.email);
      } catch (e: unknown) {
        if (active) setErrorMsg(e instanceof Error ? e.message : "Failed to load profile.");
      } finally {
        if (active) setLoading(false);
      }
    }
    loadProfile();
    return () => {
      active = false;
    };
  }, []);

  const roleKey = useMemo(() => {
    if (!user) return "student" as UserRole;
    return (user.role === "Admin" ? "admin" : user.role === "Instructor" ? "instructor" : "student") as UserRole;
  }, [user]);

  const isDirty = !!user && (firstName !== user.first_name || lastName !== user.last_name || email !== user.email);

  async function handleSave() {
    if (!user || !isDirty) return;
    setIsSaving(true);
    setSaveStatus("idle");
    setErrorMsg("");
    try {
      const res = await api.patch<ApiEnvelope<UserProfile>>("/profile", {
        first_name: firstName,
        last_name: lastName,
        email,
        department_id: user.dept_id,
      });
      setUser(res.data);
      setFirstName(res.data.first_name);
      setLastName(res.data.last_name);
      setEmail(res.data.email);
      setSaveStatus("success");
    } catch (e: unknown) {
      setSaveStatus("error");
      setErrorMsg(e instanceof Error ? e.message : "Failed to update profile.");
    } finally {
      setIsSaving(false);
    }
  }

  function handleDiscard() {
    if (!user) return;
    setFirstName(user.first_name);
    setLastName(user.last_name);
    setEmail(user.email);
    setSaveStatus("idle");
    setErrorMsg("");
  }

  if (loading) {
    return (
      <AppShell role={initialRole} userName="User" pageTitle="My Profile">
        <div className="card p-6 text-sm" style={{ color: "var(--color-text-muted)" }}>Loading profile...</div>
      </AppShell>
    );
  }

  if (!user) {
    return (
      <AppShell role={initialRole} userName="User" pageTitle="My Profile">
        <div className="card p-6 text-sm" style={{ color: "var(--color-error)" }}>{errorMsg || "Profile unavailable."}</div>
      </AppShell>
    );
  }

  return (
    <AppShell role={roleKey} userName={`${user.first_name} ${user.last_name}`} pageTitle="My Profile" isIrregular={user.role === "Student" && user.is_irregular}>
      <main className="animate-fade-in mx-auto py-6 flex flex-col gap-6">
        <section className="bg-white rounded-2xl border border-slate-200 shadow-sm p-6 sm:p-8">
          <div className="flex items-center gap-4">
            <div className="w-16 h-16 rounded-xl bg-primary flex items-center justify-center text-white font-bold text-xl">
              {getInitials(firstName, lastName)}
            </div>
            <div>
              <h1 className="text-xl font-bold">{firstName} {lastName}</h1>
              <p className="text-sm text-slate-500">{email}</p>
              <p className="text-xs text-slate-400 mt-1">Joined {formatDate(user.created_at)}</p>
            </div>
          </div>
        </section>

        <section className="bg-white rounded-2xl border border-slate-200 shadow-sm p-6 sm:p-8">
          <h2 className="text-sm font-bold uppercase tracking-widest text-slate-400 mb-5">Personal Information</h2>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-5">
            <div>
              <label className="form-label" htmlFor="first_name">First Name</label>
              <input id="first_name" value={firstName} onChange={(e) => setFirstName(e.target.value)} />
            </div>
            <div>
              <label className="form-label" htmlFor="last_name">Last Name</label>
              <input id="last_name" value={lastName} onChange={(e) => setLastName(e.target.value)} />
            </div>
            <div className="sm:col-span-2">
              <label className="form-label" htmlFor="email">Institutional Email</label>
              <input id="email" type="email" value={email} onChange={(e) => setEmail(e.target.value)} />
            </div>
          </div>

          {saveStatus === "success" && <p className="mt-4 text-sm" style={{ color: "var(--color-success)" }}>Profile updated successfully.</p>}
          {(saveStatus === "error" || errorMsg) && <p className="mt-4 text-sm" style={{ color: "var(--color-error)" }}>{errorMsg || "Failed to update profile."}</p>}

          <div className="mt-6 flex items-center gap-3">
            <button onClick={handleSave} disabled={!isDirty || isSaving} className={`btn ${isDirty && !isSaving ? "btn-primary" : "btn-ghost"}`}>
              {isSaving ? "Saving..." : "Save Changes"}
            </button>
            {isDirty && <button onClick={handleDiscard} className="btn btn-ghost">Discard</button>}
            <Link href="/change-password" className="ml-auto text-sm" style={{ color: "var(--color-primary)" }}>
              Change Password
            </Link>
          </div>
        </section>
      </main>
    </AppShell>
  );
}
